/** Every restaurant: the first ones with their rating and village, then the extra ones per food type. */
export const RESTAURANTS: Shop[] = [
  ...BASE_RESTAURANTS.map((shop) => ({ ...shop, ...RESTAURANT_INFO[shop.id] })),
  ...MORE_RESTAURANTS,
].map(restaurantPresentation);

export const MENUS: Record<number, Product[]> = { ...BASE_MENUS, ...MORE_MENUS };

/** The default list for each kind of shop. Restaurants have their own menus. */
export const CATALOG_BY_KIND: Partial<Record<ShopKind, Product[]>> = {
  fish: FISH,
  poultry: POULTRY,
  butcher: BUTCHER,
  veg: VEGETABLES,
  fruit: FRUITS,
  grocery: SUPERMARKET,
  bakery: BAKERY,
  sweets: SWEETS,
  attar: ATTAR,
  coffee: COFFEE,
  dairy: DAIRY,
  stationery: STATIONERY,
  housewares: HOUSEWARES,
  pharmacy: PHARMACY,
};

/** What a shop sells, or null when it takes a free-text order (a salon, a workshop). */
export function productsForShop(shop: Pick<Shop, 'id' | 'kind'>): Product[] | null {
  if (shop.kind === 'restaurant') return MENUS[shop.id] ?? null;
  return (shop.kind && CATALOG_BY_KIND[shop.kind]) || null;
}

/** The sections of a list, in the order they first appear. */
export function sectionsOf(products: Product[]): string[] {
  return [...new Set(products.map((p) => p.section ?? ''))];
}
